-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.apply_item_stock_quantities()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- quantityNonNettable is the part of quantityOnHand that sits in a storage
  -- unit whose effectiveNettable is false. A row with no storage unit, or one
  -- whose unit no longer exists, is nettable.
  IF TG_OP = 'INSERT' THEN
    INSERT INTO "itemStockQuantities" AS isq
      ("itemId", "companyId", "locationId", "quantityOnHand", "quantityNonNettable")
    SELECT
      b."itemId",
      b."companyId",
      COALESCE(b."locationId", ''),
      SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")),
      COALESCE(SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus"))
        FILTER (WHERE su."effectiveNettable" = false), 0)
    FROM batched_new b
    LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
    GROUP BY b."itemId", b."companyId", COALESCE(b."locationId", '')
    ORDER BY 1, 2, 3
    ON CONFLICT ("itemId", "companyId", "locationId")
    DO UPDATE SET
      "quantityOnHand" = isq."quantityOnHand" + EXCLUDED."quantityOnHand",
      "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";

  ELSIF TG_OP = 'UPDATE' THEN
    -- Generic old-vs-new: subtract every old row's contribution at its old key
    -- and add every new row's at its new key. Covers the real case (a
    -- trackedEntityStatus flip) and any future quantity/location/item edit
    -- without special-casing.
    INSERT INTO "itemStockQuantities" AS isq
      ("itemId", "companyId", "locationId", "quantityOnHand", "quantityNonNettable")
    SELECT "itemId", "companyId", "locationId", SUM(delta), SUM(non_nettable_delta)
    FROM (
      SELECT
        b."itemId",
        b."companyId",
        COALESCE(b."locationId", '') AS "locationId",
        -item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus") AS delta,
        CASE WHEN su."effectiveNettable" = false
          THEN -item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")
          ELSE 0
        END AS non_nettable_delta
      FROM batched_old b
      LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
      UNION ALL
      SELECT
        b."itemId",
        b."companyId",
        COALESCE(b."locationId", ''),
        item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus"),
        CASE WHEN su."effectiveNettable" = false
          THEN item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")
          ELSE 0
        END
      FROM batched_new b
      LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
    ) d
    GROUP BY "itemId", "companyId", "locationId"
    -- A key whose net deltas are zero already holds the right numbers; skipping
    -- it avoids taking a lock on every row a wide UPDATE happened to touch.
    HAVING SUM(delta) <> 0 OR SUM(non_nettable_delta) <> 0
    ORDER BY 1, 2, 3
    ON CONFLICT ("itemId", "companyId", "locationId")
    DO UPDATE SET
      "quantityOnHand" = isq."quantityOnHand" + EXCLUDED."quantityOnHand",
      "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";

  ELSIF TG_OP = 'DELETE' THEN
    -- Defensive: no application path deletes itemLedger rows today. A key left
    -- at zero with no backing ledger rows is removed by the nightly
    -- reconciliation.
    INSERT INTO "itemStockQuantities" AS isq
      ("itemId", "companyId", "locationId", "quantityOnHand", "quantityNonNettable")
    SELECT
      b."itemId",
      b."companyId",
      COALESCE(b."locationId", ''),
      -SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")),
      -COALESCE(SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus"))
        FILTER (WHERE su."effectiveNettable" = false), 0)
    FROM batched_old b
    LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
    GROUP BY b."itemId", b."companyId", COALESCE(b."locationId", '')
    ORDER BY 1, 2, 3
    ON CONFLICT ("itemId", "companyId", "locationId")
    DO UPDATE SET
      "quantityOnHand" = isq."quantityOnHand" + EXCLUDED."quantityOnHand",
      "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";
  END IF;

  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.storage_unit_release_non_nettable_stock(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation <> 'DELETE' THEN
    RETURN;
  END IF;

  IF COALESCE((p_old->>'effectiveNettable')::boolean, true) THEN
    RETURN;
  END IF;

  -- Deleting a unit sets its ledger rows' storageUnitId to NULL (the FK is ON
  -- DELETE SET NULL), and stock in no unit is nettable. The ledger handler
  -- cannot tell that this stock was non-nettable, because by then the unit row
  -- is gone. So release it here, before the row is deleted.
  INSERT INTO "itemStockQuantities" AS isq
    ("itemId", "companyId", "locationId", "quantityOnHand", "quantityNonNettable")
  SELECT
    il."itemId",
    il."companyId",
    COALESCE(il."locationId", ''),
    0,
    -SUM(item_ledger_on_hand_contribution(il."quantity", il."trackedEntityStatus"))
  FROM "itemLedger" il
  WHERE il."storageUnitId" = p_old->>'id'
  GROUP BY il."itemId", il."companyId", COALESCE(il."locationId", '')
  HAVING SUM(item_ledger_on_hand_contribution(il."quantity", il."trackedEntityStatus")) <> 0
  ORDER BY 1, 2, 3
  ON CONFLICT ("itemId", "companyId", "locationId")
  DO UPDATE SET "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_storage_type_nettable(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_location_ids TEXT[];
BEGIN
  IF p_operation = 'INSERT' THEN
    RETURN;
  END IF;

  IF p_operation = 'UPDATE'
    AND (p_new->'nettable') IS NOT DISTINCT FROM (p_old->'nettable') THEN
    RETURN;
  END IF;

  -- Deleting a nettable type changes no unit.
  IF p_operation = 'DELETE'
    AND COALESCE((p_old->>'nettable')::boolean, true) THEN
    RETURN;
  END IF;

  SELECT array_agg(DISTINCT su."locationId")
  INTO v_location_ids
  FROM "storageUnit" su
  WHERE su."companyId" = p_old->>'companyId'
    AND su."storageTypeIds" @> ARRAY[p_old->>'id'];

  PERFORM util.refresh_storage_unit_nettable(v_location_ids);
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_storage_unit_nettable(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  -- util.refresh_storage_unit_nettable's own write of effectiveNettable.
  IF current_setting('app.storage_unit_nettable_refresh', true) = 'on' THEN
    RETURN;
  END IF;

  IF p_operation = 'INSERT' THEN
    -- A new unit has no children and no stock, so only its own row can be
    -- wrong, and only when it is non-nettable (the column defaults to true) or
    -- arrives saying it is. A nettable insert, the usual row of a bulk import,
    -- recomputes nothing.
    IF COALESCE((p_new->>'nettable')::boolean, true)
      AND COALESCE((p_new->>'effectiveNettable')::boolean, true)
      AND NOT EXISTS (
        SELECT 1 FROM "storageType" st
        WHERE st."id" IN (SELECT jsonb_array_elements_text(
                COALESCE(p_new->'storageTypeIds', '[]'::jsonb)))
          AND st."nettable" = false
      )
      AND NOT EXISTS (
        SELECT 1 FROM "storageUnit" parent
        WHERE parent."id" = p_new->>'parentId'
          AND parent."effectiveNettable" = false
      ) THEN
      RETURN;
    END IF;
    PERFORM util.refresh_storage_unit_nettable(ARRAY[p_new->>'locationId']);
    RETURN;
  END IF;

  IF p_operation <> 'UPDATE' THEN
    RETURN;
  END IF;

  -- The inputs of effectiveNettable, and effectiveNettable itself: a write that
  -- set it directly is recomputed back.
  IF (p_new->'nettable') IS NOT DISTINCT FROM (p_old->'nettable')
    AND (p_new->'parentId') IS NOT DISTINCT FROM (p_old->'parentId')
    AND (p_new->'storageTypeIds') IS NOT DISTINCT FROM (p_old->'storageTypeIds')
    AND (p_new->'locationId') IS NOT DISTINCT FROM (p_old->'locationId')
    AND (p_new->'effectiveNettable') IS NOT DISTINCT FROM (p_old->'effectiveNettable') THEN
    RETURN;
  END IF;

  -- A move between two parents that agree changes nothing below the unit:
  -- the parent pass of a bulk import moves every row this way.
  IF (p_new->'nettable') IS NOT DISTINCT FROM (p_old->'nettable')
    AND (p_new->'storageTypeIds') IS NOT DISTINCT FROM (p_old->'storageTypeIds')
    AND (p_new->'locationId') IS NOT DISTINCT FROM (p_old->'locationId')
    AND (p_new->'effectiveNettable') IS NOT DISTINCT FROM (p_old->'effectiveNettable')
    AND COALESCE((
      SELECT parent."effectiveNettable" FROM "storageUnit" parent
      WHERE parent."id" = p_new->>'parentId'
    ), true) = COALESCE((
      SELECT parent."effectiveNettable" FROM "storageUnit" parent
      WHERE parent."id" = p_old->>'parentId'
    ), true) THEN
    RETURN;
  END IF;

  PERFORM util.refresh_storage_unit_nettable(
    ARRAY[p_new->>'locationId', p_old->>'locationId']
  );
END;
$function$;

-- event triggers (packages/database/src/event-system/attachments.ts)
SET lock_timeout = '5s';
SELECT set_event_triggers('storageType', ARRAY[]::text[], ARRAY['sync_storage_type_nettable']::text[], false, ARRAY[]::text[]);
SELECT set_event_triggers('storageUnit', ARRAY['storage_unit_enforce_same_location', 'storage_unit_block_location_change_with_children', 'storage_unit_enforce_no_cycle', 'storage_unit_release_non_nettable_stock']::text[], ARRAY['sync_storage_unit_nettable']::text[], true, ARRAY['broadcast_reference_changes']::text[]);
RESET lock_timeout;
